-- Hostel inventory import for JKKN Dental College and Hospital
-- Source: A/B/C BLOCK Excel sheet (Director-provided, 2026-05-26).
-- A BLOCK = 54 rooms, B BLOCK = 38 rooms, C BLOCK = 53 rooms.
-- C BLOCK residents: 130 matched girl learners (BDS + PharmD).
-- All operations are idempotent via ON CONFLICT DO NOTHING.
--
SET LOCAL statement_timeout = '120s';

BEGIN;

-- ===== 1. Hostel blocks =====
ON CONFLICT (id) DO NOTHING;

-- ===== 2. Hostel rooms (145 total: 54 A + 38 B + 53 C) =====
-- A BLOCK: 54 rooms
ON CONFLICT (id) DO NOTHING;

-- B BLOCK: 38 rooms
ON CONFLICT (id) DO NOTHING;

-- C BLOCK: 53 rooms
ON CONFLICT (id) DO NOTHING;

-- ===== 3. Hostel residents (130 matched girls, deduplicated by profile) =====
ON CONFLICT DO NOTHING;

COMMIT;

